component.css:
.pixel-container {
  font-family: 'Courier New', Courier, monospace;
  background: #2b2b2b;
  border: 4px solid #8b8b8b;
  box-shadow: inset -4px -4px 0 #0a0a0a, inset 4px 4px 0 #d4d4d4;
  padding: 12px 16px;
  margin: 10px 0;
  image-rendering: pixelated;
  display: inline-block;
  width: 100%;
  box-sizing: border-box;
}

.pixel-btn-group {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.pixel-btn {
  flex: 1;
  min-width: 100px;
  background: #4a4a4a;
  border: none;
  border-bottom: 6px solid #222;
  color: #b0b0b0;
  font-family: 'Courier New', Courier, monospace;
  font-weight: bold;
  font-size: 16px;
  padding: 12px 0;
  text-align: center;
  cursor: pointer;
  image-rendering: pixelated;
  transition: all 0.05s ease;
  box-shadow: inset -2px -2px 0 #1a1a1a, inset 2px 2px 0 #7a7a7a;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.pixel-btn:active {
  transform: translateY(4px);
  border-bottom-width: 2px;
}

.pixel-btn[data-active="true"] {
  background: #7cb342;
  border-bottom-color: #33691e;
  color: #0f2b0f;
  box-shadow: inset -2px -2px 0 #2e4a1e, inset 2px 2px 0 #a5d6a7;
  text-shadow: 1px 1px 0 #b9f6ca;
}

.pixel-btn:not([data-active="true"]):hover {
  background: #5e5e5e;
  color: #dfdfdf;
}

component.script:
var selected = '$selection$';

var btn1 = document.querySelector('[data-choice="1"]');
var btn2 = document.querySelector('[data-choice="2"]');


if (btn1) btn1.removeAttribute('data-active');
if (btn2) btn2.removeAttribute('data-active');


if (selected === '1' && btn1) {
  btn1.setAttribute('data-active', 'true');
} else if (selected === '2' && btn2) {
  btn2.setAttribute('data-active', 'true');
} else {
  if (btn1) btn1.setAttribute('data-active', 'true');
}


var text1 = '【开场白 1】\n你站在一片像素废墟之中，远处传来机械的轰鸣。\n冒险者，你准备好了吗？';
var text2 = '【开场白 2】\n雨夜，霓虹灯在积水路面倒映出破碎的光。\n你从梦中醒来，发现手中紧握着一张旧照片。';


var d = String.fromCharCode(36);


btn1.addEventListener('click', function() {
  var newMsg = text1 + '\n\n' + 
    '<' + d + 'openning' + d + '>' +
    '  <selection>1</selection>' +
    '</' + d + 'openning' + d + '>';
  changeMsg(newMsg);
});

btn2.addEventListener('click', function() {
  var newMsg = text2 + '\n\n' + 
    '<' + d + 'openning' + d + '>' +
    '  <selection>2</selection>' +
    '</' + d + 'openning' + d + '>';
  changeMsg(newMsg);
});
